begin
wwv_flow_imp_shared.create_automation(
 p_id=>wwv_flow_imp.id(45338268059884422822)
,p_name=>'Export Report To Drive'
,p_static_id=>'export-report-to-drive'
,p_trigger_type=>'POLLING'
,p_polling_interval=>'FREQ=DAILY;INTERVAL=1;BYHOUR=12;BYMINUTE=0'
,p_polling_status=>'DISABLED'
,p_result_type=>'ALWAYS'
,p_error_handling_type=>'ABORT'
);
wwv_flow_imp_shared.create_automation_action(
 p_id=>wwv_flow_imp.id(45338268462232422825)
,p_automation_id=>wwv_flow_imp.id(45338268059884422822)
,p_name=>'New Action'
,p_static_id=>'new-action'
,p_execution_sequence=>10
,p_action_type=>'NATIVE_PLSQL'
,p_action_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE ',
'    x_blob       BLOB;',
'    x_mime_type  VARCHAR2(1000);',
'    x_filename   VARCHAR2(1000);',
'    x_token      VARCHAR2(1000);',
'    x_fileid     VARCHAR2(1000);',
'    v_status     VARCHAR2 (4000);',
'    ',
'    x_folder_id         VARCHAR2(1000);',
'    x_client_id         VARCHAR2(1000);',
'    x_client_secret     VARCHAR2(1000);',
'    x_refresh_token     VARCHAR2(1000);',
'BEGIN',
'',
'    x_folder_id         := APEX_APP_SETTING.GET_VALUE(''FOLDER_ID'');        ',
'    x_client_id         := APEX_APP_SETTING.GET_VALUE(''CLIENT_ID'');',
'    x_client_secret     := APEX_APP_SETTING.GET_VALUE(''CLIENT_SECRET'');',
'    x_refresh_token     := APEX_APP_SETTING.GET_VALUE(''REFRESH_TOKEN'');',
'',
'    gdrive_report_export_prc (',
'        p_from_date => :P2_FROM_DATE,',
'        p_to_date => :P2_TO_DATE,',
'        x_blob        => x_blob,',
'        x_mime_type   => x_mime_type,',
'        x_filename    => x_filename',
'    );',
'    ',
'    gdrive_get_token_prc(',
'        p_client_id     => x_client_id,',
'        p_client_secret => x_client_secret,',
'        p_refresh_token => x_refresh_token,',
'        p_token         => x_token',
'    );',
'    ',
'    gdrive_upload_prc (',
'        p_blob           => x_blob,',
'        p_filename       => x_filename,',
'        p_mime_type      => x_mime_type,',
'        p_folder_id      => x_folder_id,',
'        p_access_token   => x_token,',
'        p_fileid         => x_fileid',
'    );',
'',
'    APEX_AUTOMATION.LOG_INFO(x_filename);',
'',
'EXCEPTION WHEN OTHERS THEN ',
'    APEX_AUTOMATION.LOG_ERROR (''Exception: '' || SQLERRM);',
'END;'))
,p_action_clob_language=>'PLSQL'
,p_location=>'LOCAL'
,p_stop_execution_on_error=>true
);
end;
/
