wwv_flow_imp_page.create_component_da_action(
 p_id=>wwv_flow_imp.id(44929272371436602916)
,p_button_id=>wwv_flow_imp.id(44929272004173602912)
,p_action_sequence=>10
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_static_id=>'native-execute-plsql-code'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'items_to_return', 'P2_ACCESS_TOKEN,P2_ERROR,P2_SUCCES,P2_MESSAGE,P2_FOLDER_ID',
  'items_to_submit', 'P2_FROM_DATE,P2_TO_DATE',
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'DECLARE ',
    '    x_blob       BLOB;',
    '    x_mime_type  VARCHAR2(1000);',
    '    x_filename   VARCHAR2(1000);',
    '    x_token      VARCHAR2(1000);',
    '    x_fileid     VARCHAR2(1000);',
    '    ',
    '    x_folder_id         VARCHAR2(1000);',
    '    x_client_id         VARCHAR2(1000);',
    '    x_client_secret     VARCHAR2(1000);',
    '    x_refresh_token     VARCHAR2(1000);',
    'BEGIN',
    '',
    '    :P2_ERROR:= NULL;',
    '    :P2_SUCCES:= NULL;',
    '    :P2_MESSAGE:= NULL;',
    '',
    '    x_folder_id         := APEX_APP_SETTING.GET_VALUE(''FOLDER_ID'');        ',
    '    x_client_id         := APEX_APP_SETTING.GET_VALUE(''CLIENT_ID'');',
    '    x_client_secret     := APEX_APP_SETTING.GET_VALUE(''CLIENT_SECRET'');',
    '    x_refresh_token     := APEX_APP_SETTING.GET_VALUE(''REFRESH_TOKEN'');',
    '',
    '    gdrive_report_export_prc (',
    '        p_from_date => :P2_FROM_DATE,',
    '        p_to_date => :P2_TO_DATE,',
    '        x_blob        => x_blob,',
    '        x_mime_type   => x_mime_type,',
    '        x_filename    => x_filename',
    '    );',
    '    ',
    '    gdrive_get_token_prc(',
    '        p_client_id     => x_client_id,',
    '        p_client_secret => x_client_secret,',
    '        p_refresh_token => x_refresh_token,',
    '        p_token         => x_token',
    '    );',
    '',
    '    :P2_ACCESS_TOKEN    := x_token;',
    '    :P2_FOLDER_ID       := x_folder_id;',
    '    ',
    '    gdrive_upload_prc (',
    '        p_blob           => x_blob,',
    '        p_filename       => x_filename,',
    '        p_mime_type      => x_mime_type,',
    '        p_folder_id      => x_folder_id,',
    '        p_access_token   => x_token,',
    '        p_fileid         => x_fileid',
    '    );',
    '',
    '    :P2_SUCCES:= 1;',
    '    :P2_MESSAGE:= ''Upload Successfully.'';',
    '',
    'EXCEPTION WHEN OTHERS THEN ',
    '    :P2_ERROR:= 1;',
    '    :P2_MESSAGE:= SQLERRM;',
    'END;')),
  'show_processing', 'N',
  'suppress_change_event', 'N')).to_clob
,p_stop_execution_on_error=>true
,p_wait_for_result=>true
);
