wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(45312473010976717617)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'LOAD_GOOGLE_DRIVE_FILES'
,p_static_id=>'load-google-drive-files'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_body CLOB;',
'    l_json JSON_OBJECT_T;',
'    l_files JSON_ARRAY_T;',
'    l_file JSON_OBJECT_T;',
'    l_count NUMBER;',
'BEGIN',
'    l_body := APEX_APPLICATION.G_X01;',
'',
'    l_json := JSON_OBJECT_T.PARSE(l_body);',
'',
'    l_files := l_json.GET_ARRAY(''files'');',
'',
'    APEX_COLLECTION.CREATE_OR_TRUNCATE_COLLECTION(',
'        P_COLLECTION_NAME => ''GOOGLE_DRIVE_FILES''',
'    );',
'',
'    l_count := l_files.GET_SIZE;',
'',
'    FOR i IN 0 .. l_count - 1 LOOP',
'',
'        l_file := TREAT(',
'            l_files.GET(i) AS JSON_OBJECT_T',
'        );',
'',
'        APEX_COLLECTION.ADD_MEMBER(',
'            P_COLLECTION_NAME => ''GOOGLE_DRIVE_FILES'',',
'            P_C001  => l_file.GET_STRING(''id''),',
'            P_C002  => l_file.GET_STRING(''name''),',
'            P_C003  => l_file.GET_STRING(''mimeType''),',
'            P_C004  => CASE',
'                         WHEN l_file.HAS(''size'')',
'                         THEN l_file.GET_STRING(''size'')',
'                       END,',
'            P_C005  => CASE',
'                         WHEN l_file.HAS(''modifiedTime'')',
'                         THEN l_file.GET_STRING(''modifiedTime'')',
'                       END,',
'            P_C006  => CASE',
'                         WHEN l_file.HAS(''webViewLink'')',
'                         THEN l_file.GET_STRING(''webViewLink'')',
'                       END',
'        );',
'',
'    END LOOP;',
'',
'    APEX_JSON.OPEN_OBJECT;',
'    APEX_JSON.WRITE( ''success'', TRUE );',
'    APEX_JSON.WRITE( ''count'', l_count );',
'    APEX_JSON.CLOSE_OBJECT;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        APEX_JSON.OPEN_OBJECT;',
'        APEX_JSON.WRITE(''success'',FALSE);',
'        APEX_JSON.WRITE(''message'',SQLERRM);',
'        APEX_JSON.CLOSE_OBJECT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when_button_id=>wwv_flow_imp.id(44929272004173602912)
,p_internal_uid=>41572953859796118735
);
end;
